import java.sql.*;
public class Main {public static void main(String[]a)throws Exception{String url=System.getenv().getOrDefault("DB_URL","jdbc:mysql://localhost:3306/campus");String user=System.getenv().getOrDefault("DB_USER","root"),pass=System.getenv().getOrDefault("DB_PASSWORD","");try(Connection c=DriverManager.getConnection(url,user,pass)){c.setAutoCommit(false);String sql="INSERT INTO bus_pass(pass_id,reg_no,holder,route_no) VALUES(?,?,?,?)";try(PreparedStatement ps=c.prepareStatement(sql)){for(int i=1;i<=100;i++){ps.setString(1,"P"+i);ps.setString(2,String.format("192311%03d",i));ps.setString(3,"Student "+i);ps.setInt(4,i%5+1);ps.addBatch();}int[] result=ps.executeBatch();c.commit();System.out.println("Inserted="+result.length);}}}}
